"""Incumbent navy report design, keeping the shared document and controls."""

CSS=r'''
.shell{max-width:1440px;background:transparent;padding:24px 28px 44px}header{border:0;padding-bottom:16px}header h1{display:flex;align-items:center;gap:12px;font-size:29px}.brand-mark{display:inline-grid;place-items:center;background:var(--navy);color:white;width:36px;height:36px;border-radius:7px;font:700 25px/1 "Segoe UI",sans-serif;flex:none}
nav{background:#F7FAFD;border:1px solid var(--line);border-radius:8px;padding:16px 20px;box-shadow:0 5px 14px #163b630d}nav a{font-weight:600;text-decoration:none}.opening{min-height:0;padding:20px 0 24px}.cover-grid{display:grid;grid-template-columns:1.12fr .88fr;gap:24px;align-items:stretch}.cover-panel{background:var(--navy);color:white;border-radius:8px;padding:32px 34px}.cover-kicker{color:#BBD4E9;font-weight:600}.cover-panel h2{font-size:34px;line-height:1.3;color:white;margin:18px 0 22px}.cover-panel dl{display:grid;grid-template-columns:90px minmax(0,1fr);gap:12px 18px}.cover-panel dt{color:#BBD4E9}.cover-panel dd{margin:0;font-weight:600;overflow-wrap:anywhere}.executive{background:#234C72;border-radius:6px;padding:14px 16px;margin-top:20px}.executive p{margin:6px 0}.cover-kpis{display:grid;gap:16px}.metrics{display:grid;grid-template-columns:repeat(var(--columns,3),minmax(0,1fr));gap:14px;margin:14px 0 18px}.metric{padding:16px 18px;background:#E9EEF3;border:1px solid var(--line);border-radius:6px;min-width:0}.metric-label{color:var(--muted);font-size:14px}.metric-value{font-size:29px;font-weight:700;color:var(--ink);line-height:1.35;margin:4px 0}.metric-detail{font-size:14px;color:var(--muted);overflow-wrap:anywhere}.decision{background:#EDF3F8;border:1px solid var(--line);padding:18px 22px;border-radius:7px;margin-top:20px}.decision .conclusion{color:var(--navy);font-size:23px;margin:0 0 10px}.decision h2{font-size:19px;margin:14px 0 8px}.priorities{max-width:none;margin:8px 0}.priorities li{margin:9px 0}.decision .statistics{border-top:1px solid var(--line);padding-top:12px;margin-top:14px;font-weight:600}
details.section{background:white;border:1px solid var(--line);border-radius:8px;padding:16px 22px 22px;margin:0 0 20px}.section>summary{border-bottom:1px solid #D7E0E9;margin-bottom:16px}.section>summary h2{font-size:24px;margin:0}.section-number{display:inline-block;background:var(--navy);color:white;border-radius:3px;padding:2px 9px;font-size:17px;margin-right:12px;vertical-align:2px}.subheading{margin:26px 0 14px;font-size:21px}.story{background:#D5E3EF;border-left:3px solid var(--navy);border-radius:4px;padding:14px 16px;margin:16px 0}.story strong{color:var(--navy)}.story p{margin:5px 0}.overview-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:24px;align-items:start}.distribution-panel{background:#EDF3F8;border-radius:6px;padding:18px}.ring-layout{display:flex;align-items:center;gap:20px}.ring-layout svg{width:190px;max-width:48%;height:auto}.ring-legend{display:grid;gap:15px;flex:1}.ring-legend .badge{margin-right:8px}.pass-track{height:12px;background:#E9EEF3;border-radius:2px;margin:10px 0 22px;overflow:hidden}.pass-track>span{display:block;background:#506B84;height:100%}
details.problem{background:#FAFCFE;border:1px solid #D7E0E9;border-left:3px solid var(--grade,var(--navy));border-radius:4px;padding:10px 16px 16px;margin:18px 0 24px}details.problem>summary{border:0;font-size:19px;margin:0 0 12px}.issue-fields{display:grid;grid-template-columns:82px minmax(0,1fr);gap:10px 14px;margin:16px 0 20px}.issue-fields dt{font-weight:700}.issue-fields dd{margin:0;overflow-wrap:anywhere}.issue-meta{color:var(--muted);font-size:14px;border-top:1px solid #D7E0E9;padding-top:12px}.problem ol{padding-left:26px;margin:18px 0}.problem li{padding-left:3px;margin:6px 0}.reference{margin:12px 0}.view-all{font-weight:600}
.cluster-grid{display:grid;grid-template-columns:repeat(var(--columns,2),minmax(0,1fr));gap:18px;margin:18px 0}.cluster-card{border:1px solid var(--line);padding:17px;background:#E9EEF3;min-width:0}.cluster-card h4{font-size:18px;margin:0 0 6px;overflow-wrap:anywhere}.cluster-card dl{display:grid;grid-template-columns:minmax(0,1fr);gap:5px;margin:12px 0}.cluster-card dt{font-size:14px;color:var(--ink);overflow-wrap:anywhere}.cluster-feature{display:flex;gap:16px;flex-wrap:wrap;margin:12px 0}.mini-graph{font-size:14px;margin:10px 0}.mini-graph .track{height:8px;margin-top:5px}.host-grid,.top-grid,.storage-grid,.vsan-chart-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin:16px 0}.chart{background:#E9EEF3;border:1px solid var(--line);padding:16px;border-radius:6px;margin:0;min-width:0}.chart h4{font-size:17px;margin:0 0 14px}.chart-row{grid-template-columns:minmax(0,1fr) minmax(85px,25%) 76px;gap:10px;font-size:14px}.chart-label{font-size:14px}.chart .track{height:11px;background:white}.chart .bar{background:#8CA9BF}.chart .bar.over{background:#506B84}.axis{display:grid;grid-template-columns:minmax(0,1fr) minmax(85px,25%) 76px;gap:10px;height:38px;font-size:12px;color:var(--muted)}.axis-labels{position:relative}.axis-labels span{position:absolute;white-space:nowrap}.axis-labels>span{top:8px}.axis-tick{position:absolute;top:0;height:0;border-top:1px solid var(--muted);transform-origin:0 0}.axis-tick.is-threshold{border-color:var(--navy);border-top-width:2px}.axis-labels .axis-threshold{color:var(--navy);font-weight:700}.top-card{background:#E9EEF3;border:1px solid var(--line);border-radius:6px;padding:18px;min-width:0}.top-card h4{font-size:18px;margin:0 0 5px}.top-card .scope-note{color:var(--muted);font-size:14px;margin:6px 0 15px}.top-row{margin:15px 0 19px}.top-row strong{overflow-wrap:anywhere}.top-row .rank-detail{font-size:14px;color:var(--muted);margin:3px 0 6px;overflow-wrap:anywhere}.numeric-bar{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center;font-size:15px;font-weight:600}.numeric-bar .track{background:white;height:10px}.numeric-bar .bar{background:#506B84}.storage-row{background:#F7FAFD;border:1px solid #D7E0E9;padding:12px 14px;border-radius:4px;min-width:0}.storage-row strong{overflow-wrap:anywhere}.storage-row .meta{margin:5px 0}.storage-row .track{height:10px;margin-top:8px}.storage-row .bar{background:#8CA9BF}.checklist{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 24px;padding-left:22px}.vsan-chart-grid article{background:#E9EEF3;padding:16px;border:1px solid var(--line);border-radius:5px}.vsan-chart-grid h4{margin:0 0 8px}
@media(max-width:1000px){.cover-grid,.overview-grid{grid-template-columns:1fr}.cover-kpis{grid-template-columns:repeat(3,minmax(0,1fr))}.cluster-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.metric-value{font-size:26px}.cover-panel{padding:26px}}
@media(max-width:650px){.shell{padding:16px}.cover-grid,.cover-kpis,.metrics,.cluster-grid,.host-grid,.top-grid,.storage-grid,.vsan-chart-grid,.checklist{grid-template-columns:1fr}.cover-panel{padding:22px}.cover-panel h2{font-size:29px}.cover-panel dl{grid-template-columns:76px minmax(0,1fr);gap:10px}.decision{padding:16px}details.section{padding:12px 14px 18px}.issue-fields{grid-template-columns:70px minmax(0,1fr);gap:10px}.section-number{font-size:15px;margin-right:7px}.section>summary h2{font-size:23px}.chart-row{grid-template-columns:minmax(0,1fr) 64px;gap:7px}.chart-row .chart-label{grid-column:1 / -1}.axis{grid-template-columns:minmax(0,1fr) 64px;gap:7px}.axis>span:first-child{display:none}.ring-layout{gap:12px}.ring-layout svg{width:150px}.opening{padding-top:16px}.table-scroll{max-width:100%}.cover-label{overflow-wrap:anywhere}}
@media print{.shell{padding:0}details.section{border:0;padding:0;box-shadow:none}.cover-grid{grid-template-columns:1.12fr .88fr}.cover-kpis{grid-template-columns:1fr}.cover-panel{background:#163B63!important;print-color-adjust:exact}.cover-panel h2{color:white}.metrics{grid-template-columns:repeat(var(--columns,3),minmax(0,1fr))}.host-grid,.top-grid,.storage-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.decision,.metric,.chart,.top-card,.cluster-card{print-color-adjust:exact}.story,.problem,.cluster-card,.top-card{break-inside:avoid}.opening{break-after:page}}
'''

JS=r'''
const V=D.visual;
const reference=(n,key='reference')=>n.references?.html?.[key]??n[key]??'';
function linked(t){return E(t).replace(/附录 ([A-Z]+)/g,(m,l)=>D.appendices.some(a=>a.letter===l)?`<a href="#appendix-${E(l)}">${m}</a>`:m)}
const metric=m=>`<article class="metric"><div class="metric-label">${E(m.label)}</div><div class="metric-value">${E(m.value)}</div>${m.detail?`<div class="metric-detail">${E(m.detail)}</div>`:""}</article>`;
const metrics=a=>a?.length?`<div class="metrics" style="--columns:${a.length}">${a.map(metric).join("")}</div>`:"";
const story=t=>t?`<aside class="story"><strong>检查解读</strong><p>${linked(t)}</p></aside>`:"";
function alignAxes(){
 for(const axis of document.querySelectorAll('.axis-labels')){
  const labels=[...axis.querySelectorAll(':scope>span')],width=axis.clientWidth;if(width<=0||!labels.length)continue;
  const sizes=labels.map(e=>e.getBoundingClientRect().width),gap=8;
  const extra=Math.max(0,sizes.reduce((a,b)=>a+b,0)+gap*(sizes.length-1)-width);
  const first=-extra/2,last=width+extra/2-sizes.at(-1);let end=first;
  axis.querySelectorAll(':scope>i').forEach(e=>e.remove());
  labels.forEach((label,i)=>{
   const anchor=Number(label.dataset.fraction)*width;
   const x=i===0?first:i===labels.length-1?last:Math.max(end+gap,Math.min(anchor-sizes[i]/2,last-gap-sizes[i]));
   label.style.left=x+'px';label.style.top='8px';label.style.transform='none';
   const target=i===0||i===labels.length-1?anchor:x+sizes[i]/2,dx=target-anchor;
   const tick=document.createElement('i');tick.className='axis-tick'+(label.classList.contains('axis-threshold')?' is-threshold':'');
   Object.assign(tick.style,{left:anchor+'px',width:Math.hypot(dx,4)+'px',transform:`rotate(${Math.atan2(4,dx)}rad)`});axis.append(tick);
   end=x+sizes[i];
  });
 }
}
const statecard=c=>c?`<article class="metric vm-state-card"><strong>${E(c.title)}</strong><p>${c.segments.map(s=>E(s.label)+' '+E(s.value)).join(' · ')}</p>${c.total>0?`<div class="state-track" style="display:flex;height:12px">${c.segments.filter(s=>s.value>0).map(s=>`<span style="width:${100*s.value/c.total}%;background:${E(s.color)}"></span>`).join('')}</div>`:""}</article>`:"";
function graph(g){if(g.equal_text)return `<div class="chart"><h4>${E(g.title)}</h4><p>${E(g.equal_text)}</p></div>`;
 return `<article class="chart"><h4>${E(g.title)}</h4>${g.series.map(r=>`<div class="chart-row"><span class="chart-label">${E(r.name)}${r.detail?` · ${E(r.detail)}`:""}</span><div class="track"><span class="bar ${r.value>g.threshold?"over":""}" style="width:${100*r.value/g.axis_max}%"></span><span class="threshold" style="left:${100*g.threshold/g.axis_max}%"></span></div><span class="value">${E(r.text)}</span></div>`).join("")}<div class="axis"><span></span><div class="axis-labels">${[...g.ticks].sort((a,b)=>a.value-b.value).map((t,i)=>`<span class="${t.value===g.threshold?"axis-threshold":""}" data-fraction="${t.value/g.axis_max}" style="left:${100*t.value/g.axis_max}%;transform:translateX(${i===0?"0":i===g.ticks.length-1?"-100%":"-50%"})">${E(t.text)}</span>`).join("")}</div><span></span></div>${g.more?`<p class="reference">${linked(reference(g,'more'))}</p>`:""}</article>`}
function problem(p){const highest=D.sections.find(s=>s.kind==='problems')?.items[0]?.level;
 return `<details class="problem" style="--grade:${E(D.colors[p.level])}" id="problem-${E(p.id)}" ${p.level===highest?"open":""}><summary>${badge(p.level)} ${E(p.title)}</summary>${p.capacity_note?`<p>${E(p.capacity_note)}</p>`:""}<dl class="issue-fields">${p.fields.map(f=>`<dt>${E(f.label)}：</dt><dd>${E(f.text)}</dd>`).join("")}</dl>${p.render_groups.map(g=>`${g.title?`<h4>${E(g.title)}</h4>`:""}<ol>${g.steps.map(step=>`<li>${E(step)}</li>`).join("")}</ol>`).join("")}${p.visual.meta.length?`<p class="issue-meta">${p.visual.meta.map(f=>E(f.label)+"："+E(f.value)).join(" · ")}</p>`:""}${table(p.representative_table)}${p.references.html?`<p class="reference">${linked(p.references.html)}</p>`:""}${p.objects>5?`<p><a class="view-all" href="#appendix-${E(p.appendix)}">查看全部 ${E(p.objects)} ${E(p.unit)}</a></p>`:""}${p.object_notes.filter(n=>n.startsWith('NSX Manager 的资源预留')).map(n=>`<p>${E(n)}</p>`).join("")}</details>`}
function cluster(c){return `<article class="cluster-card"><h4>${E(c.name)}</h4><div class="meta">${E(c.summary)}</div><div class="cluster-feature">${c.features.map(f=>`<span>${E(f.label)} ${E(f.value)}</span>`).join("")}</div><dl>${c.fields.map(f=>`<dt>${E(f.label)}：${E(f.value)}</dt>`).join("")}</dl>${c.graphs.map(g=>`<div class="mini-graph"><strong>${E(g.title)} · ${E(g.text)}</strong><div class="track"><span class="bar" style="width:${g.value}%"></span></div></div>`).join("")}${c.host_names?`<p class="meta">主机：${E(c.host_names)}</p>`:""}${c.cpu_models?`<p class="meta">CPU 型号：${E(c.cpu_models)}</p>`:""}</article>`}
function topcard(n){return `<article class="top-card"><h4>${E(n.title)}</h4>${n.notes.map(note=>`<p class="scope-note">${E(note)}</p>`).join("")}${V.top[n.id].map(r=>`<div class="top-row"><strong>${E(r.rank)}. ${E(r.name)}</strong><p class="rank-detail">主机 ${E(r.host)}${r.host_share_text?` · 占比 ${E(r.host_share_text)}`:""}</p><div class="numeric-bar"><div class="track"><span class="bar" style="width:${r.bar_pct}%"></span></div><span>${E(r.display)}</span></div></div>`).join("")}</article>`}
function block(n){if(n.presentation==='ranked-cards')return topcard(n);
 if(n.kind==='cards')return `<div class="cluster-grid" style="--columns:${n.rows.length}">${n.rows.map(r=>cluster(V.clusters[r.name])).join("")}</div>`;
 if(n.kind==='chart')return graph(n);
 if(n.kind==='paragraph')return ['environment-identity','capacity-note','judgment-boundary'].includes(n.id)?`<p class="meta">${linked(reference(n,'text'))}</p>`:story(reference(n,'text'));
 return `<h4>${E(n.title)}</h4>${table({...n,notes:n.references?.html?.notes??n.notes})}${n.reference?`<p class="reference">${linked(reference(n))}</p>`:""}`;
}
function group(g){let content='';
 if(g.id==='scale-clusters')content=metrics(V.asset_kpis)+statecard(V.vm_state_card)+metrics(V.snapshots)+story(V.narratives.clusters);
 if(g.id==='host-resources')content=metrics(V.host_kpis)+story(V.narratives.hosts)+`<div class="host-grid">${['allocation_cpu','allocation_memory'].filter(k=>V[k]).map(k=>graph(V[k])).join("")}</div><div class="host-grid">${g.blocks.filter(n=>n.kind==='chart'&&n.id!=='memory_allocation_pct').map(graph).join("")}</div>`;
 if(g.id==='storage')content=metrics(V.vsan_cards);
 if(g.id==='resource-top')return `<section><h3 class="subheading">${E(g.title)}</h3><div class="top-grid">${g.blocks.map(topcard).join("")}</div></section>`;
 if(['network','security-certificates'].includes(g.id))content=story(V.group_summaries[g.id].text);
 for(const n of g.blocks){
  if(['scale','snapshot-overview'].includes(n.id)||(g.id==='host-resources'&&n.kind==='chart')||(['network','security-certificates'].includes(g.id)&&n.kind==='paragraph'))continue;
  if(n.id==='storage-ranking')content+=`<h4>${E(n.title)}</h4><div class="storage-grid">${n.rows.map(row=>{const r=V.storage[row.name];return `<article class="storage-row"><strong>${E(row.name)}</strong><p class="meta">${E(r.usage_text)}${r.clusters?.length?` · ${E(r.clusters.join('、'))}`:""}</p>${r.capacity_text?`<p class="meta">${E(r.capacity_text)}</p>`:""}<div class="track"><span class="bar" style="width:${r.usage}%"></span></div></article>`}).join("")}</div>${(n.references?.html?.notes??n.notes).map(note=>`<p class="reference">${linked(note)}</p>`).join("")}`;
  else content+=block(n);
 }
 if(g.id==='scale-clusters'&&V.cluster_coverage.length)content+=`<div class="metrics" style="--columns:${V.cluster_coverage.length}">${V.cluster_coverage.map(c=>`<article class="metric"><strong>${E(c.title)} · ${E(c.value)}/${E(c.total)}</strong><div class="pass-track"><span style="width:${100*c.value/c.total}%"></span></div>${c.text?`<p class="metric-detail">${E(c.text)}</p>`:""}</article>`).join('')}</div>`;
 if(g.id==='storage')content+=`<div class="vsan-chart-grid">${V.vsan_charts.map(c=>`<article><h4>${E(c.title)}</h4><p>${E(c.text)}</p><p>${c.segments.map(r=>E(r.label)+' '+E(r.display)).join(' · ')}</p>${c.total>0?`<div class="track"><span class="bar" style="width:${100*c.segments[0].value/c.total}%"></span></div>`:""}</article>`).join('')}</div>`;
 return `<section><h3 class="subheading">${E(g.title)}</h3>${content}</section>`;
}
document.getElementById('opening').innerHTML=`<div class="cover-grid"><div class="cover-panel"><div class="cover-kicker">客户交付报告</div>${V.cover_label?`<p class="cover-label">${E(V.cover_label)}</p>`:""}<h2>${E(V.display_title)}</h2><dl>${[['客户名称',D.customer],['巡检日期',D.date],['平台版本',V.platform]].filter(r=>r[1]).map(([l,t])=>`<dt>${E(l)}</dt><dd>${E(t)}</dd>`).join('')}</dl>${D.opening.statistics?`<div class="executive"><strong>执行摘要</strong><p>${E(D.opening.statistics)}</p></div>`:""}</div><div class="cover-kpis">${V.opening_kpis.map(metric).join('')}</div></div><div class="decision"><p class="conclusion">总体结论：${E(D.opening.conclusion)}</p>${D.opening.priorities.length?`<h2>需优先处理的问题</h2><ul class="priorities">${D.opening.priorities.map(p=>`<li>${badge(p.level)}<span>${E(p.title)} · ${E(p.objects)} 个受影响对象</span></li>`).join('')}</ul>`:""}${D.opening.more?`<p><a href="#overview">${E(D.opening.more)}</a></p>`:""}${D.opening.statistics?`<p class="statistics">${E(D.opening.statistics)}</p>`:""}</div>`;
document.getElementById('body-sections').innerHTML=D.sections.map((s,i)=>{let body='';
 if(s.kind==='overview'&&!V.has_execution_stats){body=table({id:'overview',title:s.title,weights:[1,5,1],headers:['等级','问题类别','受影响对象'],rows:s.rows.map((r,j)=>({id:'overview'+j,cells:[r.level,r.title,r.objects]}))})}
 else if(s.kind==='overview'){const t={id:'overview',title:s.title,weights:[1,5,1],headers:['等级','问题类别','受影响对象'],rows:s.rows.map((r,j)=>({id:'overview'+j,cells:[r.level,r.title,r.objects]}))};body=metrics([['检查总数','total'],['通过','passed'],['未通过','failed']].map(([l,k])=>({label:l,value:D.statistics[k],detail:''})))+`<p class="meta">通过比例 ${E(V.scope.pass_percent_text)}</p><div class="pass-track"><span style="width:${V.scope.pass_percent}%"></span></div><div class="overview-grid">${table(t)}<article class="distribution-panel"><h3>未通过检查结果按等级分布</h3><div class="ring-layout">${V.scope_svg}<div class="ring-legend">${V.scope.level_distribution.map(r=>`<div>${badge(r.level)} <span>${E(r.count)} 条 · ${E(r.share_pct_text)}</span></div>`).join('')}</div></div></article></div>`}
 else if(s.kind==='problems')body=s.items.map(problem).join('');
 else if(s.kind==='checklist')body=`<ul class="checklist">${s.items.map(r=>`<li>✓ ${E(r.label)}</li>`).join('')}</ul>`;
 else if(s.kind==='environment')body=s.groups.map(group).join('');
 return `<details class="section" id="${E(s.id)}" ${s.kind==='overview'||s.kind==='problems'?'open':''}><summary><h2 style="display:inline"><span class="section-number">${String(i+1).padStart(2,'0')}</span>${E(s.title)}</h2></summary>${body}</details>`;
}).join('');
const axesObserver=new ResizeObserver(alignAxes);document.querySelectorAll('.axis-labels').forEach(e=>axesObserver.observe(e));document.fonts.ready.then(alignAxes);alignAxes();

'''

def apply(base_css,base_js):
    start=base_js.index('document.getElementById("opening").innerHTML=')
    end=base_js.index('document.getElementById("appendix-tables").innerHTML=')
    css=CSS.replace('.cover-panel h2','.cover-panel .cover-title')
    css+='\n.cover-title{font-weight:700}.report-name{min-width:0;overflow-wrap:anywhere}header h1{min-width:0}\n'
    js=JS.replace('<h2>${E(V.display_title)}</h2>','<p class="cover-title">${E(V.display_title)}</p>')
    js=js.replace('p.references.html','p.reference')
    js=js.replace('V.clusters[r.name]','V.clusters[r.key]').replace('V.storage[row.name]','V.storage[row.key]')
    js=js.replace('<p class="rank-detail">主机 ${E(r.host)}${r.host_share_text?` · 占比 ${E(r.host_share_text)}`:""}</p>',
                  '${r.meta_text?`<p class="rank-detail">${E(r.meta_text)}</p>`:""}')
    js=js.replace('${body}</details>`;','${V.section_subtitles[s.kind]?`<p class="meta section-subtitle">${E(V.section_subtitles[s.kind])}</p>`:""}${body}</details>`;')
    return base_css+'\n'+css,base_js[:start]+js+'\n'+base_js[end:]
